def next_action(result):
    """Determine the next action based on the command result.

    Args:
        result: The result dictionary from the previous tool execution.
            Expected keys: 'tool', 'process_id', 'exit_code', 'status'.
            - If 'tool' is 'get_process_status', check 'status' and 'exit_code'.
            - If 'tool' is 'run_command', ignore (do not repeat).

    Returns:
        dict: Next action dict based on the result.
            - If status is 'running', return {"tool": "get_process_status", "process_id": <id>}.
            - If status is 'completed' with exit_code 0, return {"tool": "final_report", "success": True}.
            - If status is 'completed' with exit_code != 0 or 'failed', return {"tool": "final_report", "success": False}.
            - If status is unknown, raise ValueError.
    """
    if result.get('tool') == 'run_command':
        # Do not repeat run_command, proceed to check status
        pass
    elif result.get('tool') == 'get_process_status':
        status = result.get('status')
        exit_code = result.get('exit_code')

        if status == 'running':
            return {"tool": "get_process_status", "process_id": result.get('process_id')}
        elif status == 'completed':
            if exit_code == 0:
                return {"tool": "final_report", "success": True}
            else:
                return {"tool": "final_report", "success": False}
        elif status == 'failed':
            return {"tool": "final_report", "success": False}
        else:
            raise ValueError("Unknown process status")
    else:
        raise ValueError("Unknown tool in result")

    # Default case for 'run_command' result (no status yet)
    if 'process_id' in result:
        return {"tool": "get_process_status", "process_id": result.get('process_id')}
    else:
        raise ValueError("Missing process_id in result")

import protocol
import json

def test_next_action_with_running_status():
    # Test case for running status
    result = {
        "tool": "get_process_status",
        "status": "running",
        "process_id": 123
    }
    action = protocol.next_action(result)
    assert action == {"tool": "get_process_status", "process_id": 123}

def test_next_action_with_successful_completion():
    # Test case for completed with exit_code 0
    result = {
        "tool": "get_process_status",
        "status": "completed",
        "exit_code": 0
    }
    action = protocol.next_action(result)
    assert action == {"tool": "final_report", "success": True}

def test_next_action_with_failed_completion():
    # Test case for completed with exit_code != 0
    result = {
        "tool": "get_process_status",
        "status": "completed",
        "exit_code": 1
    }
    action = protocol.next_action(result)
    assert action == {"tool": "final_report", "success": False}

